<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderDirectAccessAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderDirectAccessAccessor trait.
 *
 * Covers null default, string/VO assignment via withDirectAccess,
 * getDirectAccess/directAccess accessors, and isDirectAccessChanged with/without original.
 */
class TenantLoginProviderDirectAccessAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDirectAccess creates a new instance with the DirectAccess set
     * from a string value, and getDirectAccess returns the primitive string.
     */
    public function testWithDirectAccessFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDirectAccessAccessorUnitTest();

        // Act
        $result = $holder->withDirectAccess(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isDirectAccess());
    }
    /**
     * Asserts that withdirectAccess has access to the value object
     * from a string value, and getDirectAccess returns the primitive string.
     */
    public function testWithDirectAccessFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDirectAccessAccessorUnitTest();

        // Act
        $result = $holder->withDirectAccess(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->directAccess()->value());
    }
    public function testChangedDirectAccess(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDirectAccessAccessorUnitTest();
        $original = $holder->withDirectAccess( true);
        $same = $holder->withDirectAccess( true);
        $modified = $holder->withDirectAccess(false);

        // Act
        $unchanged = $holder->isDirectAccessChanged();
        $withSame = $original->isDirectAccessChanged( $same );
        $withDiferent = $original->isDirectAccessChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderDirectAccessAccessorUnitTest
{
  use TenantLoginProviderDirectAccessAccessor;
}
